              text: '大江东去，浪淘尽，千古风流人物。\n故垒西边，人道是，三国周郎赤壁。\n乱石穿空，惊涛拍岸，卷起千堆雪。\n江山如画，一时多少豪杰。\n\n遥想公瑾当年，小乔初嫁了，雄姿英发。\n羽扇纶巾，谈笑间，樯橹灰飞烟灭。\n故国神游，多情应笑我，早生华发。\n人生如梦，一尊还酹江月。',
              note: '写这首时他四十五岁，正在黄州种地。**这一首初中课本没收（高中部编必修上册收了），但它是苏轼最有名的一首词，也是豪放词的代表作。**\n\n注意他把谁写了进来：周瑜。赤壁那一仗打起来时，周瑜三十四岁，已经名满天下、指挥了一场改变历史的战争。而写这首词的苏轼，四十五岁，在一个荒州被看管着。\n\n所以「多情应笑我，早生华发」不是自嘲，是**他真在拿自己和周瑜比**。最后那句「人生如梦」，不是丧气，是一个人把落差想明白之后，举起酒杯说的那句话。'
