              text: '元丰六年十月十二日夜，解衣欲睡，月色入户，欣然起行。念无与为乐者，遂至承天寺寻张怀民。怀民亦未寝，相与步于中庭。庭下如积水空明，水中藻、荇交横，盖竹柏影也。何夜无月？何处无竹柏？但少闲人如吾两人者耳。',
              note: '**课本坐标：统编版八年级上册第三单元，初中课文里最短的一篇之一，全文八十五个字。**\n\n「庭下如积水空明」——他把洒在院子里的月光，写成了满院子都是水；「藻、荇交横」是水草，其实是竹子和柏树的影子。**一个被贬官的人，把地上的影子看成了水草。**\n\n最要紧的是最后一句「但少闲人如吾两人者耳」。他不是真的闲，是**没资格忙**。可他把这个「闲」字，写成了一种本事。\n\n（一起散步的张怀民，当时也是被贬到黄州的人。）'
