            '## 五、今天能带走的那一点',
            '',
            '黄州这五年，最值得注意的地方在于：**他什么都没能改变。**',
            '',
            '官还是那个不许上班的官，地方还是那个荒州。他后来也没有等来道歉，也没有等来平反。',
