            "",
            "**他不是在京城撑不住了才走，是看清了在那儿待下去没有意义，所以自己先走。**",
            "",
            "- 1089 年那次外任，是他反复上章求来的；",
            "- 到了杭州，他也没把「被排挤出京」当回事，而是去干一件当时最要紧、也最不风光的活：挖湖。",
            "",
            "**同样是「离开中心」，有人是被推着走的，有人是自己走出去的。**区别在于：自己走出去的人，手里还有一件自己认的事可做。",
            "",
            "他五十几岁那几年，位置越换越远，做出来的东西反而越来越实——一条堤、一座病坊、一个州的水利。**这些是能留下来的。**"
