            '',
            '塾师说：读书，登第，就像你父亲那样。',
            '',
            '他摇头：登第恐怕不是第一等的事，**读书学圣贤**才是。',
            '',
            '老师的答案是那个时代**最标准的答案**；他的答案是那个时代**最不像答案的答案**。功名是别人给的，圣贤是自己要做的——一个十二岁的孩子，把这两件事分开了。',
