              "**一、明代人结婚，一天走的是哪几道礼**",
              "",
              "- **纳采**：男方托媒人送礼物提亲，古书里写「委禽」，送的是雁",
              "- **问名**：问女方名字、生辰",
              "- **纳吉**：占卜得吉，正式定下",
