            '真正的转折，是他从表哥文运昌那里借到的两本东西。',
            '',
            '第一本是郑观应写的《盛世危言》。这本书讲的是外国人为什么强、中国为什么弱，铁路、轮船、学校这些东西是怎么一回事。他后来说，读了这本书，**他第一次有了「政治意识」**——原来一个国家是可以被讨论、被改造的。',
            '',
            '第二本是一本讲列强瓜分中国的小册子，开头第一句是：',
            '',
            '> **「呜呼，中国其将亡矣！」**',
            '',
            '他说他读完那句，心里堵得难受，第一次感到**国家兴亡，匹夫有责**。',
            '',
