            '',
            '## 四、账本里的那张纸',
            '',
            '一九一〇年，他十七岁。',
            '',
            '湘乡县办了一所新式小学堂，叫东山高等小学堂。那里不教四书五经，教算术、地理、英语——是另一个世界。',
            '',
            '他想去。父亲不让。一个要当家的长子，跑去读「洋学堂」？家里谁记账？',
            '',
            '他的做法我特别想让你注意：**他没有跟父亲硬顶。他去说服了母亲，又请表哥文运昌、塾师毛宇居一起去劝父亲。**',
            '',
            '一个十七岁的孩子，已经懂了一件事——**想让一件难的事办成，得先团结能替你说话的人。**',
            '',
            '还有一个细节：他是湘潭人，要进湘乡的学堂得有人担保。他是靠人情、靠关系，一步一步把这道门推开的。',
            '',
            '父亲最后同意了。临走那个早上，他抄了一首诗，夹在父亲的账本里：',
            '',
            '> **孩儿立志出乡关，学不成名誓不还。埋骨何须桑梓地，人生无处不青山。**',
            '',
            '（这诗原本是日本人西乡隆盛写的，他把「男儿」改成「孩儿」，把「死不还」改成「誓不还」。改得很轻，但意思变了：**原句是赌命，改后是立志。**）',
            '',
            '到了东山学堂，他穿的是乡下的土布衣服，说话是湘潭口音，同学笑他「土」。但作文写得好，学堂的堂长读过他的文章，很赏识他。',
            '',
            '**一个被人笑的乡下孩子，是靠那一手字和那一点见识站稳的。**',
            '',
            '## 五、今天能带走的那一点',
            '',
            '这个人后来走过的路你都知道：井冈山、长征、延安、天安门。',
            '',
