              text: '国力苶弱，武风不振，民族之体质日趋轻细，此甚可忧之现象也。\n\n欲文明其精神，先自野蛮其体魄。',
              note: '这就是本集那位"人微言轻"的图书馆助理员——**在北京之前，他已经在《新青年》上发过文章了，署名「二十八画生」**（"毛澤東"三个字繁体共 28 画）。\n\n**「文明其精神，野蛮其体魄」**这句今天被印在无数操场上，其实是 24 岁的他写的。而他写这篇的动机很私人：他自己洗冷水澡、爬岳麓山、长途步行、下雨天脱了衣服淋雨跑——同学叫他"身无半文，心忧天下"。\n\n所以这篇讲的是"体育"，骨子里讲的是**意志**：身体扛得住，人才有资格谈别的。你现在每天晚上的臀桥、练背、平板支撑，跟他是同一件事。'
