            '',
            '第二件是**游学**。一九一七年暑假，他和同学萧子升身上一文钱不带，走遍长沙附近五个县，靠给人写对联换饭吃，一个多月走了近千里。**这不是穷游，是去看真实的中国长什么样。**',
            '',
            '第三件是**组人**。一九一八年四月，他和蔡和森、萧子升这些人在长沙成立了一个团体，叫**新民学会**。最初会员只有十几个人，规矩很严：不谈金钱，不谈男女，只谈学问和国家。',
            '',
            '「团结能替你说话的人」这个本事，从十七岁那张账本纸，到二十五岁这个学会，是一路练出来的。',
            '',
            '## 二、北京：最冷的一次',
            '',
            '一九一八年八月，他第一次去北京。',
