            '',
            '那一年在北大的，全是中国最顶尖的人：陈独秀、李大钊、胡适、蔡元培。**他后来回忆说，那些有名的人一个个都很忙，没有一个愿意跟一个讲南方话的助理员多说一句话。**',
            '',
            '他一个月挣八块钱。当时北大教授的月薪是几百块。',
            '',
            '他自己用的词是四个字：**人微言轻**。想找人谈谈政治、谈谈文化，没有人听他讲。',
            '',
            '## 三、可他偏偏在这半年带走了两样东西',
            '',
            '第一样：**李大钊**。图书馆主任李大钊很照顾这个年轻人。就是在北大图书馆，他第一次读到了马克思主义的书刊。',
            '',
            '第二样：**杨开慧**。在北京，他和老师的女儿重新认识，后来结了婚。',
            '',
            '所以北京那半年，是他一生最不被看见的一段，**也是他拿到方向的一段**。',
            '',
            '一九二〇年他第二次到北京，读到三本书：**《共产党宣言》《阶级斗争》《社会主义史》**。他说过，就是这三本书，让他建立起对马克思主义的信仰。',
            '',
            '## 四、今天能带走的那一点',
            '',
            '这里有一个很反直觉的点：',
            '',
