            { title: '反对本本主义', tag: '文章 · 1930 年', why: '「**没有调查，没有发言权**」的出处——**下一段就讲它**，先记着这句话。它的反面就是你现在最容易踩的坑：坐在那儿想"我该怎么办"，而不是先去看看"事情到底是什么样"。' }
