              text: '一国之内，在四围白色政权的包围中间，产生一小块或若干小块的红色政权区域，在世界上是一件奇事。\n这种奇事的发生，有其独特的原因。而其存在和发展，亦必有相当的条件。',
              note: '**《毛泽东选集》第一卷里的一篇。注意它讲的是「条件」，不是「决心」。**\n\n当时的通行想法是「只要敢拼就能赢」；他反过来先问：这件事能成立，靠的是哪几条具体条件？把条件数清楚，一个人才知道劲该往哪儿使。\n\n这一篇跟他同一时期的《井冈山的斗争》是一对，可以连着读——前一篇讲「为什么能存在」，后一篇讲「怎么维持下去」。'
