              note: '**《毛泽东选集》第一卷收尾的一篇。**它原来的题目叫《时局估量和红军行动问题》，是一封信。写它，是因为当时队伍里有人泄气，问「红旗到底能打多久」。\n\n「星星之火，可以燎原」这八个字本身出自《尚书·盘庚上》「若火之燎于原」——他借的是一句三千年前的老话。\n\n这一段的用法：**当你觉得手上的事太小、没有意义的时候，别急着放弃——先问一句「它有没有柴可以烧」。**'
