              '**一、私塾分两种**',
              '',
              '- **蒙馆**：教认字、写字、算账。读的是《三字经》《百家姓》《千字文》《幼学琼林》。',
              '- **经馆**：往上读经书、练八股，目标是科举。读的是「四书」「五经」。',
