              text: "乃知其治乱之源、富强之本，不尽在船坚炮利，而在议院上下同心，教养得法；\n兴学校，广书院，重技艺，别考课，使人尽其才；\n讲农学，利水道，化瘠土为良田，使地尽其利；\n造铁路，设电线，薄税敛，保商务，使物畅其流。",
              note: "**跟这一集什么关系：**这一集第三节讲的就是它。这段话的结构很值得看一眼——**先否掉一个流行答案（船坚炮利），再给三个「使人尽其才／使地尽其利／使物畅其流」。**一个十五岁的少年读到这样的句子，会第一次发现：原来国家的事是可以一条一条列出来的。\n\n**课本坐标**：统编版初中语文未收《盛世危言》。历史教材讲洋务运动、戊戌变法时会提到早期维新派，郑观应是这一路人的代表，但一般不引原文。**拿来当「议论文怎么排比说理」的例子很好用**——四句一串，全是一个句式。"
